"""The `sapn_summary` parser (D3 §5.3, §13). Every file is generated by `make_sources` or edited from its output."""

import json
from datetime import date, datetime

import pytest

from energatron.adapters.sources.sapn_summary import SAPN_SUMMARY, SapnSummaryParser
from energatron.core.errors import InvalidInputError
from energatron.core.models.catalog import Coverage, SourceInfo, SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_nem12 import sapn_filename
from tests.fixtures.make_sources import SummaryRow, make_pdf, make_sapn_summary_csv
from tests.fixtures.synthetic import SYNTHETIC_NMI, SYNTHETIC_NMI11, SYNTHETIC_SERIAL

GENERATED = datetime(2025, 3, 2, 9, 8, 7)
WINDOW = (date(2025, 1, 1), date(2025, 3, 2))
NAME = sapn_filename("SUMMARY", SYNTHETIC_NMI, WINDOW, GENERATED)
PDF_NAME = sapn_filename("SUMMARY", SYNTHETIC_NMI, WINDOW, GENERATED, ext="pdf")
RENAMED = "summary.csv"
ROWS = (
    SummaryRow(date(2025, 1, 1), date(2025, 1, 31)),
    SummaryRow(date(2025, 2, 1), date(2025, 2, 28), quality="E"),
)
REQUESTED = {"start": "2025-01-01", "end": "2025-03-02"}


def csv(rows: tuple[SummaryRow, ...] = ROWS, **kw: str) -> bytes:
    return make_sapn_summary_csv(rows, **kw)


def pdf(**kw: object) -> bytes:
    pdf_kw: dict[str, object] = {"creation_date": "D:20250302091500+10'30'"}
    pdf_kw.update(kw)
    return make_pdf(**pdf_kw)  # type: ignore[arg-type]


def inspect(data: bytes, filename: str = NAME) -> SourceInfo:
    return SAPN_SUMMARY.inspect(filename, data)


def reason(data: bytes, filename: str = NAME) -> str:
    with pytest.raises(InvalidInputError) as caught:
        inspect(data, filename)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    return value


def edit(data: bytes, old: str, new: str) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, 1).encode("utf-8")


def test_the_parser_is_a_source_parser_for_sapn_summary_version_1() -> None:
    parser: SourceParser = SAPN_SUMMARY
    assert isinstance(SAPN_SUMMARY, SapnSummaryParser)
    assert parser.source is SourceType.SAPN_SUMMARY and parser.version == 1


# --- detect ---------------------------------------------------------------------------------------------------------


def test_detect_filename_and_content_for_csv_and_pdf() -> None:
    for name, data in ((NAME, csv()), (PDF_NAME, pdf())):
        detection = SAPN_SUMMARY.detect(name, data)
        assert detection is not None and detection.evidence == ("filename", "content")


def test_detect_content_only() -> None:
    for name, data in ((RENAMED, csv()), ("scan.pdf", pdf())):
        detection = SAPN_SUMMARY.detect(name, data)
        assert detection is not None and detection.evidence == ("content",)


def test_detect_filename_only() -> None:
    detection = SAPN_SUMMARY.detect(NAME, b"hello\r\n")
    assert detection is not None and detection.evidence == ("filename",)


def test_detect_neither() -> None:
    assert SAPN_SUMMARY.detect(RENAMED, b"hello\r\n") is None
    assert SAPN_SUMMARY.detect(NAME.replace("SUMMARY", "DETAILED"), b"200,x\n") is None


def test_the_filename_extension_is_case_insensitive() -> None:
    detection = SAPN_SUMMARY.detect(NAME.replace(".csv", ".CSV"), b"")
    assert detection is not None and detection.evidence == ("filename",)
    assert SAPN_SUMMARY.detect(NAME.replace("SUMMARY", "summary"), b"") is None


@pytest.mark.parametrize(
    ("old", "new"),
    [(",kWh,", ",kW,"), (",kW\r", ",kWh\r"), ("01/01/2025", "2025-01-01"), (",kW\r", ",kW,extra\r")],
)
def test_detect_rejects_other_first_lines(old: str, new: str) -> None:
    assert SAPN_SUMMARY.detect(RENAMED, edit(csv(), old, new)) is None


def test_detect_skips_blank_lines_and_a_bom_and_takes_lf() -> None:
    data = b"\xef\xbb\xbf\r\n" + csv().replace(b"\r\n", b"\n")
    detection = SAPN_SUMMARY.detect(RENAMED, data)
    assert detection is not None and detection.evidence == ("content",)


def test_detect_needs_only_the_first_64_kib() -> None:
    many = tuple(SummaryRow(date(2025, 1, 1), date(2025, 1, 1)) for _ in range(1500))
    data = csv(many)
    assert len(data) > 64 * 1024
    detection = SAPN_SUMMARY.detect(NAME, data[: 64 * 1024])
    assert detection is not None and detection.evidence == ("filename", "content")


# --- inspect, CSV ---------------------------------------------------------------------------------------------------


def test_inspect_a_csv() -> None:
    info = inspect(csv())
    assert info.source_ts == GENERATED
    assert info.coverage == Coverage(start=date(2025, 1, 1), end=date(2025, 2, 28))
    assert info.extra == {"format": "csv", "rows": 2, "requested_window": REQUESTED, "source_ts_from": "filename"}
    assert info.identifiers == {"nmi": [SYNTHETIC_NMI11], "meter_serial": [SYNTHETIC_SERIAL]}
    assert info.extension == ".csv"


def test_a_renamed_csv_takes_the_latest_end_date_at_midnight() -> None:
    rows = (SummaryRow(date(2025, 2, 1), date(2025, 2, 28)), SummaryRow(date(2025, 1, 1), date(2025, 1, 31)))
    info = inspect(csv(rows), RENAMED)
    assert info.source_ts == datetime(2025, 2, 28)
    assert info.coverage == Coverage(start=date(2025, 1, 1), end=date(2025, 2, 28))
    assert info.extra["source_ts_from"] == "content"
    assert info.extra["requested_window"] is None
    assert info.identifiers == {"nmi": [SYNTHETIC_NMI11], "meter_serial": [SYNTHETIC_SERIAL]}


def test_identifiers_take_every_distinct_value() -> None:
    data = csv() + csv((ROWS[0],), nmi11="ZZTEST00024", serial="SYN0000002")
    info = inspect(data)
    assert info.identifiers == {
        "nmi": [SYNTHETIC_NMI11, "ZZTEST00024"],
        "meter_serial": [SYNTHETIC_SERIAL, "SYN0000002"],
    }
    assert info.extra["rows"] == 3


def test_extra_never_holds_an_identifier() -> None:
    for info in (inspect(csv()), inspect(pdf(), PDF_NAME)):
        text = json.dumps(info.extra)
        for value in (SYNTHETIC_NMI, SYNTHETIC_SERIAL):
            assert value not in text


@pytest.mark.parametrize(
    ("old", "new", "expected"),
    [
        (",kW\r", ",kW,x\r", "bad_field_count"),
        (",kWh,", ",MWh,", "bad_row"),
        (",kW\r", ",MW\r", "bad_row"),
        ("31/01/2025", "31/13/2025", "bad_date"),
        ("31/01/2025", "2025-01-31", "bad_date"),
        ("31/01/2025", "31/12/2024", "bad_date_range"),
        (",1.000,", ",one,", "bad_number"),
        (",0.500,", ",,", "bad_number"),
    ],
)
def test_malformed_csv_rows(old: str, new: str, expected: str) -> None:
    assert reason(edit(csv(), old, new)) == expected


def test_a_malformed_second_row_is_caught() -> None:
    data = csv()
    lines = data.split(b"\r\n")
    lines[1] = lines[1].replace(b"28/02/2025", b"30/02/2025")
    assert reason(b"\r\n".join(lines)) == "bad_date"


def test_an_empty_csv_has_no_data() -> None:
    assert reason(b"\r\n\r\n") == "no_data"


def test_not_utf8() -> None:
    assert reason(csv() + b"\xff\r\n") == "not_utf8"


def test_a_bad_filename_time_is_bad_filename() -> None:
    bad = NAME.replace(f"_{GENERATED:%Y%m%d%H%M%S}_", "_20251399000000_")
    assert reason(csv(), bad) == "bad_filename"


def test_crlf_lf_and_a_bom_are_accepted() -> None:
    info = inspect(b"\xef\xbb\xbf" + csv().replace(b"\r\n", b"\n"))
    assert info.extra["rows"] == 2


# --- inspect, PDF ---------------------------------------------------------------------------------------------------


def test_inspect_a_pdf() -> None:
    info = inspect(pdf(), PDF_NAME)
    assert info.source_ts == GENERATED
    assert info.coverage is None
    assert info.extra == {"format": "pdf", "requested_window": REQUESTED, "source_ts_from": "filename"}
    assert info.identifiers == {"nmi": [SYNTHETIC_NMI11]}
    assert info.extension == ".pdf"


def test_a_renamed_pdf_takes_the_creation_date() -> None:
    info = inspect(pdf(), "scan.pdf")
    assert info.source_ts == datetime.fromisoformat("2025-03-02T09:15:00+10:30")
    assert info.extra == {"format": "pdf", "requested_window": None, "source_ts_from": "pdf_metadata"}
    assert info.identifiers == {}


def test_pdf_reasons() -> None:
    assert reason(pdf(truncated=True), PDF_NAME) == "truncated"
    assert reason(pdf(creation_date=None), "scan.pdf") == "no_creation_date"


def test_a_named_pdf_needs_no_creation_date() -> None:
    assert inspect(pdf(creation_date=None), PDF_NAME).source_ts == GENERATED


def test_confirm_takes_any_csv_and_a_pdf_whose_text_names_a_meter_summary() -> None:
    assert SAPN_SUMMARY.confirm("x.csv", b"anything,csv\n")
    summary = make_pdf(creation_date=None, text=("Data Meter Summary Format", "NMI: <NMI>"))
    assert SAPN_SUMMARY.confirm("scan.pdf", summary)
    assert not SAPN_SUMMARY.confirm("scan.pdf", make_pdf(creation_date=None, text=("Tax invoice", "NMI <NMI>")))
    assert not SAPN_SUMMARY.confirm("scan.pdf", make_pdf(creation_date="D:2025"))
